import os
import re
import xml.etree.ElementTree as ET

print("=== COMPREHENSIVE PROJECT AUDIT ===")

# 1. Define all valid routes generated by Next.js
VALID_ROUTES = {
    '/',
    '/about',
    '/pricing',
    '/subscription',
    '/faq',
    '/contact',
    '/guide-installation',
    '/guide-installation/firestick',
    '/guide-installation/samsung-smart-tv',
    '/guide-installation/lg-smart-tv',
    '/guide-installation/android-tv',
    '/guide-installation/apple-tv',
    '/guide-installation/iphone',
    '/guide-installation/android',
    '/guide-installation/windows',
    '/guide-installation/mac',
    '/blog',
    '/blog/how-to-install-iptv-on-amazon-firestick',
    '/blog/how-to-install-iptv-on-samsung-smart-tv',
    '/blog/how-to-stop-iptv-buffering-guide',
    '/blog/best-iptv-player-apps-smart-tv-firestick',
    '/blog/complete-master-us-iptv-setup-guide',
    '/terms',
    '/privacy-policy',
    '/refund-policy'
}

# 2. Check sitemap.xml
tree = ET.parse('public/sitemap.xml')
root = tree.getroot()
ns = {'sm': 'http://www.sitemaps.org/schemas/sitemap/0.9'}
sitemap_urls = [loc.text.strip() for loc in root.findall('.//sm:loc', ns)]
print(f'Sitemap URL count: {len(sitemap_urls)}')

sitemap_errors = []
for url in sitemap_urls:
    if not url.startswith('https://www.televoiptv.us'):
        sitemap_errors.append(f'Invalid domain in sitemap: {url}')
    path = url.replace('https://www.televoiptv.us', '')
    if not path:
        path = '/'
    if path not in VALID_ROUTES:
        sitemap_errors.append(f'Sitemap path not in valid routes: {path}')

if sitemap_errors:
    print('Sitemap Errors:', sitemap_errors)
else:
    print('Sitemap check: PASS (All URLs match valid routes and domain https://www.televoiptv.us)')

# 3. Check internal links in JSX files and blog post data
internal_links = set()
broken_links = []

# Scan JSX and JS files in src
for root_dir, _, files in os.walk('src'):
    for f in files:
        if f.endswith(('.jsx', '.js')):
            p = os.path.join(root_dir, f)
            with open(p, 'r', encoding='utf-8') as fh:
                content = fh.read()
                # Find Link href
                matches = re.findall(r'<Link[^>]+href=[\'"](/[^#\'"?]+)[\'"]', content)
                for m in matches:
                    internal_links.add((m, p))
                    if m not in VALID_ROUTES:
                        broken_links.append((m, p))
                # Find <a> href in blog HTML
                a_matches = re.findall(r'<a[^>]+href=[\'"](/[^#\'"?]+)[\'"]', content)
                for m in a_matches:
                    internal_links.add((m, p))
                    if m not in VALID_ROUTES:
                        broken_links.append((m, p))

print(f'Unique internal links checked: {len(internal_links)}')
if broken_links:
    print('Broken internal links found:', broken_links)
else:
    print('Internal links check: PASS (All internal links point to valid pages)')

# 4. Check images referenced in code
missing_images = []
for root_dir, _, files in os.walk('src'):
    for f in files:
        if f.endswith(('.jsx', '.js', '.css')):
            p = os.path.join(root_dir, f)
            with open(p, 'r', encoding='utf-8') as fh:
                content = fh.read()
                # Match image extensions
                img_matches = re.findall(r'[\'\"\(](/([a-zA-Z0-9_\-\./]+\.(?:svg|png|jpg|jpeg|webp)))[\'\"\)]', content)
                for full_ref, rel_path in img_matches:
                    disk_path = os.path.join('public', rel_path.replace('/', os.sep))
                    if not os.path.exists(disk_path):
                        missing_images.append((full_ref, p))

if missing_images:
    print('Missing images referenced in code:', missing_images)
else:
    print('Referenced images check: PASS (All referenced images exist in public/)')

# 5. Check for unwanted UK remnants
print('Checking for unwanted UK remnants...')
uk_patterns = [
    re.compile(r'televoiptvs?\.uk', re.I),
    re.compile(r'televoiptv\.co\.uk', re.I),
    re.compile(r'£\d+'),
    re.compile(r'\bGBP\b'),
    re.compile(r'\bBritish English\b', re.I),
    re.compile(r'\bUK market\b', re.I),
    re.compile(r'\bUK customers\b', re.I),
    re.compile(r'\bUK households\b', re.I),
]

uk_remnants = []
for root_dir, _, files in os.walk('src'):
    for f in files:
        if f.endswith(('.jsx', '.js', '.css')):
            p = os.path.join(root_dir, f)
            with open(p, 'r', encoding='utf-8') as fh:
                lines = fh.readlines()
                for line_idx, line in enumerate(lines, 1):
                    for pat in uk_patterns:
                        if pat.search(line):
                            uk_remnants.append((p, line_idx, line.strip()))

if uk_remnants:
    print(f'Found {len(uk_remnants)} UK remnants:')
    for item in uk_remnants[:10]:
        print(f'  {item[0]}:{item[1]} -> {item[2]}')
else:
    print('UK remnants check: PASS (Zero unwanted UK remnants found in src/)')
